<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Kanban Board</title>
  <style>
    :root {
      color-scheme: light;
      --background: #f4f6fb;
      --surface: #ffffff;
      --border: #e2e7f0;
      --text: #182033;
      --muted: #6d7588;
      --accent: #5267df;
      --accent-soft: #e9edff;
      --danger: #d84b5b;
      --shadow: 0 8px 24px rgba(31, 43, 78, 0.08);
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      background:
        radial-gradient(circle at top left, #eef1ff 0, transparent 35%),
        var(--background);
      color: var(--text);
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
        "Segoe UI", sans-serif;
    }

    .app {
      width: min(1180px, calc(100% - 32px));
      margin: 0 auto;
      padding: 42px 0 56px;
    }

    .topbar {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 24px;
      margin-bottom: 28px;
    }

    .title-block h1 {
      margin: 0;
      font-size: clamp(1.8rem, 4vw, 2.6rem);
      letter-spacing: -0.04em;
    }

    .title-block p {
      margin: 8px 0 0;
      color: var(--muted);
    }

    .add-card-form {
      display: flex;
      width: min(100%, 430px);
      padding: 6px;
      border: 1px solid var(--border);
      border-radius: 14px;
      background: var(--surface);
      box-shadow: var(--shadow);
    }

    #new-card {
      min-width: 0;
      flex: 1;
      border: 0;
      outline: 0;
      padding: 10px 12px;
      background: transparent;
      color: var(--text);
      font: inherit;
    }

    #new-card::placeholder {
      color: #99a0b1;
    }

    #add-card {
      border: 0;
      border-radius: 10px;
      padding: 10px 18px;
      background: var(--accent);
      color: white;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      transition: background 160ms ease, transform 160ms ease;
    }

    #add-card:hover {
      background: #4055cb;
    }

    #add-card:active {
      transform: translateY(1px);
    }

    .board {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 20px;
      align-items: start;
    }

    .column {
      min-height: 430px;
      padding: 16px;
      border: 1px solid var(--border);
      border-radius: 18px;
      background: rgba(255, 255, 255, 0.68);
      transition: border-color 160ms ease, background 160ms ease,
        transform 160ms ease;
    }

    .column.drag-over {
      border-color: var(--accent);
      background: var(--accent-soft);
      transform: translateY(-2px);
    }

    .column-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 14px;
      padding: 2px 2px 10px;
    }

    .column-header h2 {
      margin: 0;
      font-size: 1rem;
      letter-spacing: -0.01em;
    }

    .count {
      display: inline-grid;
      min-width: 28px;
      height: 28px;
      place-items: center;
      border-radius: 999px;
      background: #e9ecf3;
      color: #555f73;
      font-size: 0.82rem;
      font-weight: 800;
    }

    #col-todo .column-header {
      border-bottom: 3px solid #7889e8;
    }

    #col-doing .column-header {
      border-bottom: 3px solid #e2a33e;
    }

    #col-done .column-header {
      border-bottom: 3px solid #50ae78;
    }

    .card-container {
      min-height: 340px;
      display: flex;
      flex-direction: column;
      gap: 12px;
    }

    .card {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 12px;
      padding: 16px;
      border: 1px solid var(--border);
      border-radius: 13px;
      background: var(--surface);
      box-shadow: 0 5px 15px rgba(35, 47, 79, 0.07);
      cursor: grab;
      transition: opacity 150ms ease, transform 150ms ease,
        box-shadow 150ms ease;
    }

    .card:hover {
      transform: translateY(-2px);
      box-shadow: 0 9px 22px rgba(35, 47, 79, 0.11);
    }

    .card.dragging {
      opacity: 0.45;
      cursor: grabbing;
    }

    .card-title {
      min-width: 0;
      overflow-wrap: anywhere;
      line-height: 1.45;
      font-weight: 650;
    }

    .card-del {
      flex: 0 0 auto;
      display: grid;
      width: 28px;
      height: 28px;
      padding: 0;
      place-items: center;
      border: 0;
      border-radius: 8px;
      background: #f2f3f7;
      color: var(--muted);
      font-size: 1.1rem;
      line-height: 1;
      cursor: pointer;
      transition: color 150ms ease, background 150ms ease;
    }

    .card-del:hover {
      background: #ffe8eb;
      color: var(--danger);
    }

    button:focus-visible,
    input:focus-visible,
    .card:focus-visible {
      outline: 3px solid rgba(82, 103, 223, 0.28);
      outline-offset: 2px;
    }

    @media (max-width: 800px) {
      .topbar {
        align-items: stretch;
        flex-direction: column;
      }

      .add-card-form {
        width: 100%;
      }

      .board {
        grid-template-columns: 1fr;
      }

      .column {
        min-height: 240px;
      }

      .card-container {
        min-height: 150px;
      }
    }

    @media (max-width: 440px) {
      .app {
        width: min(100% - 20px, 1180px);
        padding-top: 24px;
      }

      #add-card {
        padding-inline: 13px;
      }
    }
  </style>
</head>
<body>
  <main class="app">
    <header class="topbar">
      <div class="title-block">
        <h1>Kanban Board</h1>
        <p>Organize tasks and move work forward.</p>
      </div>

      <form class="add-card-form" id="add-card-form">
        <input
          id="new-card"
          type="text"
          placeholder="Add a new task…"
          aria-label="New card title"
          autocomplete="off"
        >
        <button id="add-card" type="submit">Add card</button>
      </form>
    </header>

    <section class="board" aria-label="Kanban board">
      <section class="column" id="col-todo" data-column="todo">
        <header class="column-header">
          <h2>To Do</h2>
          <span class="count" aria-label="0 cards">0</span>
        </header>
        <div class="card-container" aria-label="To Do cards"></div>
      </section>

      <section class="column" id="col-doing" data-column="doing">
        <header class="column-header">
          <h2>Doing</h2>
          <span class="count" aria-label="0 cards">0</span>
        </header>
        <div class="card-container" aria-label="Doing cards"></div>
      </section>

      <section class="column" id="col-done" data-column="done">
        <header class="column-header">
          <h2>Done</h2>
          <span class="count" aria-label="0 cards">0</span>
        </header>
        <div class="card-container" aria-label="Done cards"></div>
      </section>
    </section>
  </main>

  <script>
    (() => {
      "use strict";

      const STORAGE_KEY = "kanban-board-state";
      const columnNames = ["todo", "doing", "done"];
      const columns = Array.from(document.querySelectorAll(".column"));
      const form = document.getElementById("add-card-form");
      const input = document.getElementById("new-card");
      let draggedCard = null;

      function makeId() {
        if (window.crypto && typeof window.crypto.randomUUID === "function") {
          return window.crypto.randomUUID();
        }
        return "card-" + Date.now() + "-" + Math.random().toString(36).slice(2);
      }

      function createCard(title, id = makeId()) {
        const card = document.createElement("article");
        card.className = "card";
        card.id = id;
        card.draggable = true;
        card.tabIndex = 0;

        const titleElement = document.createElement("span");
        titleElement.className = "card-title";
        titleElement.textContent = title;

        const deleteButton = document.createElement("button");
        deleteButton.className = "card-del";
        deleteButton.type = "button";
        deleteButton.textContent = "×";
        deleteButton.setAttribute("aria-label", "Delete " + title);

        card.append(titleElement, deleteButton);
        return card;
      }

      function updateCounts() {
        columns.forEach((column) => {
          const count = column.querySelectorAll(".card").length;
          const countElement = column.querySelector(".count");
          countElement.textContent = String(count);
          countElement.setAttribute(
            "aria-label",
            count + (count === 1 ? " card" : " cards")
          );
        });
      }

      function getState() {
        const state = {};

        columns.forEach((column) => {
          const key = column.dataset.column;
          state[key] = Array.from(column.querySelectorAll(".card")).map((card) => ({
            id: card.id,
            title: card.querySelector(".card-title").textContent
          }));
        });

        return state;
      }

      function saveState() {
        try {
          localStorage.setItem(STORAGE_KEY, JSON.stringify(getState()));
        } catch (error) {
          console.warn("Unable to save the board.", error);
        }
      }

      function loadState() {
        let state = null;

        try {
          const saved = localStorage.getItem(STORAGE_KEY);
          if (saved) state = JSON.parse(saved);
        } catch (error) {
          console.warn("Unable to restore the board.", error);
        }

        if (!state || typeof state !== "object") {
          updateCounts();
          return;
        }

        columnNames.forEach((name) => {
          const container = document.querySelector(
            '[data-column="' + name + '"] .card-container'
          );
          const cards = Array.isArray(state[name]) ? state[name] : [];

          cards.forEach((item) => {
            if (item && typeof item.title === "string") {
              container.appendChild(createCard(item.title, item.id || makeId()));
            }
          });
        });

        updateCounts();
      }

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        const title = input.value.trim();

        if (!title) return;

        document
          .querySelector("#col-todo .card-container")
          .appendChild(createCard(title));

        input.value = "";
        updateCounts();
        saveState();
        input.focus();
      });

      document.querySelector(".board").addEventListener("click", (event) => {
        const deleteButton = event.target.closest(".card-del");
        if (!deleteButton) return;

        deleteButton.closest(".card").remove();
        updateCounts();
        saveState();
      });

      columns.forEach((column) => {
        column.addEventListener("dragstart", (event) => {
          const card = event.target.closest(".card");
          if (!card) return;

          draggedCard = card;
          card.classList.add("dragging");

          if (event.dataTransfer) {
            event.dataTransfer.effectAllowed = "move";
            event.dataTransfer.setData("text/plain", card.id);
          }
        });

        column.addEventListener("dragover", (event) => {
          event.preventDefault();
          column.classList.add("drag-over");

          if (event.dataTransfer) {
            event.dataTransfer.dropEffect = "move";
          }
        });

        column.addEventListener("dragleave", (event) => {
          if (!column.contains(event.relatedTarget)) {
            column.classList.remove("drag-over");
          }
        });

        column.addEventListener("drop", (event) => {
          event.preventDefault();

          let card = draggedCard;
          if (event.dataTransfer) {
            const id = event.dataTransfer.getData("text/plain");
            if (id) card = document.getElementById(id) || card;
          }

          if (card) {
            column.querySelector(".card-container").appendChild(card);
            card.classList.remove("dragging");
          }

          columns.forEach((item) => item.classList.remove("drag-over"));
          draggedCard = null;
          updateCounts();
          saveState();
        });

        column.addEventListener("dragend", () => {
          if (draggedCard) draggedCard.classList.remove("dragging");
          columns.forEach((item) => item.classList.remove("drag-over"));
          draggedCard = null;
        });
      });

      loadState();
    })();
  </script>
</body>
</html>
